dp[0][0] = 0;
for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= m; j++) {
        if (dp[i-1][j] < INF) {
            dp[i][j] = min(dp[i][j], dp[i-1][j]);
            if (j + a[i] <= m) dp[i][j + a[i]] = min(dp[i][j + a[i]], dp[i-1][j] + 1);
        }
    }
}

