#include <cstring>
using namespace std;

long long dp[25][25];

long long solve(int n, int m) {
    if (n == 0) return m == 0 ? 1 : 0;
    if (dp[n][m] != -1) return dp[n][m];
    return dp[n][m] = solve(n-1, m) + solve(n-1, m-1);
}

